  "What the acquisition stage of the last preparation found at the source: its traffic, and every resource's outcome.": "最近一次准备的采集阶段在来源处的发现：其流量，以及每个资源的结果。",
  "A recorded source package: no source is checked at preparation; the recorded documents are read locally.": "记录来源包：准备时不检查任何来源，直接在本地读取记录文件。",
  "No source check yet for this book: the first preparation reads the official inventory and fetches only what the workspace does not hold.": "本账本尚无来源检查：第一次准备会读取官方清单，只下载工作区未持有的部分。",
  "A packet is prepared for this book as of an earlier cutoff; the owner binds its source check to that preparation and projects none for this cutoff. A new preparation checks the source as of now.": "本账本已有按更早截止时间准备的数据包；所有者把来源检查绑定在那次准备上，对当前截止时间不投影任何检查。新的准备会按现在的时间检查来源。",
  "without a source": "无来源",
  "{b} retained": "已留存 {b}",
  "{o} observed against a {c} cap; checked again after {d}": "观测到 {o}，上限 {c}；{d} 之后再次检查",
  "{w} of {n} issuers hold a document": "{n} 家发行人中 {w} 家持有文件",
  "{n} history shard": "{n} 个历史分片",
  "{n} history shards": "{n} 个历史分片",
  "{n} resource of the check": "本次检查的 {n} 个资源",
  "{n} resources of the check": "本次检查的 {n} 个资源",
  "No source": "无来源",
  "Prepared": "已准备",
  "Analyzed": "已分析",
  "Complete": "完成",
  "Empty": "空",
  "prepare, or admit a source": "准备，或获准一个来源",
  "The workspace holds this issuer's admitted documents; they are verified against their references at use, never assumed current.": "工作区持有该发行人的已获准文件；使用时按其引用校验，从不假定为最新。",
  "No admitted document is held for this issuer; nothing is invented for it.": "未持有该发行人的任何已获准文件；不为其编造任何内容。",
  "The unit's packet is prepared and readable; a prepared packet is not an analysis.": "该单元的数据包已准备且可读；已准备的数据包不是分析。",
  "An analysis is published for the unit; an analysis is not a CRO decision.": "该单元已发布分析；分析不是 CRO 决定。",
  "A published review read this unit's analysis.": "已发布的评审读取了该单元的分析。",
  "No preparation has reached this unit.": "尚无准备到达该单元。",
  "The body the workspace held was reused without a request, verified against its reference.": "工作区已持有的正文未经请求直接复用，并按其引用校验。",
  "The body was transferred from the official locator in this check.": "本次检查从官方地址传输了该正文。",
  "Every item the owner expected was delivered; nothing is said about what was not planned.": "所有者预期的每一项均已交付；对未纳入计划的部分不作陈述。",
  "Nothing expected was available; every failure is named.": "预期项目均不可得；每个失败都已点名。",
  "Nothing was expected and nothing was delivered.": "无预期项目，亦无交付。",
  "The disk has too little free space for the preparation's writes, so nothing of it was placed. Free space on the disk or through the storage cleanup preview, then prepare again.": "磁盘剩余空间不足以完成本次准备的写入，因此未放置任何内容。请释放磁盘空间或通过存储清理预览释放，然后重新准备。",
  "This packet was prepared under a contract this workspace has since superseded: what it read stays readable by its handles; its reading plan is not continued. Read the source preview again and prepare under the current contract.": "该数据包是在本工作区此后已取代的契约下准备的：它读到的内容仍可按句柄读回，但其阅读计划不再续读。请重新读取来源预览，并在当前契约下准备。",
  "The packet's cutoff window has expired, so more of its source cannot be read under it. Read the source preview again to prepare as of a new cutoff; the old packet stays readable.": "该数据包的截止窗口已过期，无法在其下继续读取来源。请重新读取来源预览，按新的截止时间准备；旧数据包仍可读。",
  "The packet's cutoff window has expired. Read the source preview again to prepare as of a new cutoff; the old packet stays readable.": "该数据包的截止窗口已过期。请重新读取来源预览，按新的截止时间准备；旧数据包仍可读。",
  "The packet was prepared under a contract this workspace has since superseded; what it read stays readable. Read the source preview again and prepare under the current contract.": "该数据包是在本工作区此后已取代的契约下准备的；它读到的内容仍可读。请重新读取来源预览，并在当前契约下准备。",
  "The workspace's evidence authority changed under the captured intent, so nothing was prepared. Read the source preview again for the current binding.": "工作区的证据授权在已捕获的意图之下发生了变化，因此未做任何准备。请重新读取来源预览以获得当前绑定。",
  "The acquisition window of this request has closed, so nothing was fetched. Read the source preview again for a new window.": "该请求的采集窗口已关闭，因此未下载任何内容。请重新读取来源预览以获得新的窗口。",
  "Too few of the unit's issuers hold an admitted document for the admitted floor, so the unit was refused whole and is reported as not reviewed by that name; the other units are unaffected.": "该单元中持有已获准文件的发行人少于获准下限，因此整个单元被拒绝，并以此名义报告为未评审；其他单元不受影响。",
  "A required baseline filing is not held for this issuer under the admitted cap, so the issuer fails by that name; its siblings are unaffected. An oversize body is checked again after its recheck date or under a larger declared cap.": "在获准上限之下未持有该发行人必需的基线申报，因此该发行人以此名义失败；其他发行人不受影响。超大小正文会在复查日期之后或更大的声明上限下再次检查。",
  "The body exceeds the admitted document cap and was not transferred; it is deferred by name until its recheck date or a larger declared cap.": "该正文超出获准的文件上限，未被传输；以此名义延期至复查日期或更大的声明上限。",
  "The preparation Task failed and its owner recorded the code; Tasks holds the recovery actions.": "准备任务失败，其所有者已记录代码；恢复动作见任务页。",
