  "An identical execution is already {state} as task {task}. RUN joins that in-flight work instead of starting another; its computation is unfinished and no result exists yet.": "完全相同的执行已作为任务 {task} 处于 {state} 状态。RUN 会接入这项进行中的工作而不会另起一项；其计算尚未完成，目前没有结果。",
  "An identical execution was interrupted as task {task} and needs recovery. RUN reports it as in flight and does not restart it; recover it from Tasks before a result can exist.": "完全相同的执行曾作为任务 {task} 被中断，需要恢复。RUN 会将其报告为进行中而不会重启；请先在任务页恢复它，之后才可能有结果。",
  "An identical execution exists as task {task} in state {state}. RUN returns that state instead of starting new work; resolve it before this declaration can produce a result.": "完全相同的执行以任务 {task} 存在，状态为 {state}。RUN 会返回该状态而不会开始新的工作；先处理它，此声明才可能产生结果。",
  "Saved results, current/default inputs and strategy authority. Numerical calls estimated for a fresh execution: {n}; this preview made none.": "已保存结果、当前/默认输入与策略权威。全新执行的预计数值调用：{n}；本次预览未发生任何调用。",
