  "The owner acts on exactly this Task version; if it changes before you confirm, you will be shown the new state instead.": "所有者只作用于此任务版本；若在确认前发生变化，将改为向你展示新状态。",
  "Resume this retained Task?": "恢复此已保留的任务？",
  "This Task kind has no result reader in the workbench; open it from the original product.": "此任务类型在工作台中没有结果阅读器；请在原产品中打开。",
  "Guanyin · G0 read-only · health {health} · no remediation attempted by this view · model facts not observed by this Host": "观音 · G0 只读 · 健康 {health} · 本视图未尝试任何修复 · 本 Host 未观察模型事实",
  "operation returning": "操作返回中",
  "Not sent: the Task changed since you reviewed it and is now {state} (version {version}). Review it again.": "未发送：自你查看后任务已变化，现为 {state}（版本 {version}）。请重新查看。",
  "Sent and refused by Task Control without a change: the Task had moved to {state} (version {version}) before the owner acted. Review it again.": "已发送并被 Task Control 拒绝、无任何变更：在所有者执行前任务已变为 {state}（版本 {version}）。请重新查看。",
  "Sent and refused at the operation entry without a change: the Task is now {state} (version {version}). Review it again.": "已发送并在操作入口被拒绝、无任何变更：任务现为 {state}（版本 {version}）。请重新查看。",
  "Confirmed resume refused at Task Control": "已确认的恢复被 Task Control 拒绝",
  "Worker stop": "工作进程停止",
  "runner heartbeat #{n}": "执行器心跳 #{n}",
  "Task Control timestamp only; a runner heartbeat store could not be read, so a signal may be hidden": "仅 Task Control 时间戳；某个执行器心跳存储无法读取，信号可能被遮蔽",
  "Task Control timestamp only; the recorded heartbeat is not bound to this execution": "仅 Task Control 时间戳；记录的心跳未绑定到此执行",
  "Task Control timestamp only; no runner heartbeat recorded for this execution": "仅 Task Control 时间戳；此执行没有记录的执行器心跳",
  "No data API key": "不需要数据 API 密钥",
  "This workspace holds no research input. One explicit preparation captures the current index members, acquires their daily history, builds Features and publishes one verified input. Opening this page starts nothing.": "这个工作区还没有研究输入。一次明确的准备会捕获当前指数成员、获取其日线历史、构建特征并发布一个经验证的输入。打开本页不会启动任何工作。",
  "Local market data is present but no research input is published. The preview reuses qualified local data without downloading; its qualification is checked there.": "本地已有市场数据，但尚未发布研究输入。预览会复用合格的本地数据而不下载；数据是否合格在预览时核对。",
  "Profile": "配置档",
  "History and cutoff": "历史与截止",
  "Named by the preview: the owner sets the target session and the initial history there.": "由预览确定：所有者在预览时给出目标交易日与初始历史。",
  "{n} years of daily bars before the target session {d}": "目标交易日 {d} 之前 {n} 年的日线数据",
  "Current S&P 500, NASDAQ-100 and DJIA members, merged; named exactly at preview": "当前 S&P 500、NASDAQ-100 与 DJIA 成员的合并集；确切范围在预览时给出",
  "Sources and access": "来源与访问",
  "What may use the network, what stays local, and what is not asked for.": "哪些会使用网络、哪些保留在本地、哪些不会被索取。",
  "current members · network, only after confirmation": "当前成员 · 网络访问，仅在确认之后",
  "daily bars and corporate actions · network, only after confirmation": "日线与公司行为 · 网络访问，仅在确认之后",
  "Local: the DuckDB working copy, the Features and the immutable research inputs stay in this workspace.": "本地：DuckDB 工作副本、特征与不可变研究输入都保存在这个工作区。",
  "Current-universe research only: historical index membership is not supplied.": "仅限当前成员研究：不提供历史指数成员。",
  "No data API key is requested or stored.": "不索取也不保存数据 API 密钥。",
  "Preparation activates no Foundation or strategy.": "准备工作不会激活任何 Foundation 或策略。",
  "Preparation scope · preview": "准备范围 · 预览",
  "Recorded by the owner as a plan; nothing has been admitted. Confirming is a separate step.": "所有者已将其记录为计划；尚未接纳任何任务。确认是单独的一步。",
  "Confirmation unavailable": "无法确认",
  "Awaiting confirmation": "等待确认",
  "Confirm preparation": "确认准备",
