  "Approve the change and update data": "批准变更并更新数据",
  "Market data now through": "行情数据当前截至",
  "Features now through": "特征当前截至",
  "The workspace already holds the target session: the owner checks the due sources and reuses the unchanged data and Features exactly; no Task is admitted when nothing changed.": "工作区已持有目标交易日：所有者检查到期的来源，并精确复用未变的数据与特征；若无任何变化则不接纳任务。",
  "Fetch the sessions after the current cutoff for every admitted member, maintain the Features and the Panel for them, publish one update receipt; no Factor research.": "为每个已接纳成员抓取当前截止日之后的交易日，为其维护特征与面板，发布一份更新回执；不做因子研究。",
  "The configured provider, after this confirmation; no data API key is requested.": "确认后访问已配置的数据提供方；不索取数据 API 密钥。",
  "Network access must be admitted explicitly for this service; the owner stops by name otherwise.": "本服务需要显式准许网络访问；否则所有者会具名停止。",
  "Membership sources": "成员来源",
  "Due: the current index memberships are read again before the fetch.": "到期：抓取前会重新读取当前指数成员。",
  "Not due: the last membership check stands.": "未到期：沿用上次成员检查。",
  "Data recheck": "数据复核",
  "Published input versions, saved research and every selection. Foundation research is retained as it is.": "已发布输入版本、已保存研究与全部选择。Foundation 按原样保留。",
  "Confirming admits one update Task through the data owner. It may reach the configured source for the target session; saved research, published input versions and every selection stay unchanged. Nothing is downloaded before this confirmation, and an unchanged workspace is reused exactly rather than rebuilt.": "确认后通过数据所有者接纳一个更新任务。它可能为目标交易日访问已配置的来源；已保存研究、已发布输入版本与全部选择保持不变。确认前不会下载任何内容；未变化的工作区会被精确复用而非重建。",
  "No update can be planned now ({code}): {why}": "现在无法制定更新计划（{code}）：{why}",
  "the workspace has a pending membership transition that the data owner must resolve first; the preparation page shows it.": "工作区有待处理的成员过渡，须由数据所有者先行处理；准备页面会显示它。",
  "the owner named no plan to confirm.": "所有者没有给出可确认的计划。",
  "Admitted as Task {id}; its progress is on Tasks and here once it settles.": "已作为任务 {id} 接纳；其进展见任务页，完成后也会显示在此。",
  "Nothing to update: the workspace already holds {target}. The owner reused the receipt of {at} exactly; no Task was started and nothing was downloaded.": "无需更新：工作区已持有 {target}。所有者精确复用了 {at} 的回执；没有启动任务，也没有下载任何内容。",
  "The update continues as Task {id}; the Data page shows its work.": "更新以任务 {id} 继续；数据页面显示其工作。",
  "Continue this data update": "继续此数据更新",
  "Why it stopped": "停止原因",
  "Not before {time}": "不早于 {time}",
  "Asks the owner to continue under the same plan; it refuses if the retry is not due.": "请求所有者按同一计划继续；若重试未到期则会拒绝。",
  "Validate the request": "校验请求",
  "Check the plan against the workspace as it stands now.": "对照工作区当前状态校验计划。",
  "Maintain data and Features": "维护数据与特征",
  "Fetch the new sessions for every admitted member, govern quality, maintain the Features and verify the Panel.": "为每个已接纳成员抓取新交易日，治理质量，维护特征并验证面板。",
  "Publish the receipt": "发布回执",
  "Seal one receipt of what changed; working data stays separate from published inputs.": "封存一份变更回执；工作数据与已发布输入保持分离。",
  "Checking that the workspace still matches the plan this Task was admitted with: the same membership revision, data revision and Panel; a moved workspace stops here by name.": "检查工作区是否仍与接纳此任务时的计划一致：同一成员修订、数据修订与面板；若工作区已变动则在此具名停止。",
  "Fetching the sessions after the current cutoff for every admitted member, one bounded cycle at a time; then quality governance, the Features and the Panel for the new sessions.": "为每个已接纳成员抓取当前截止日之后的交易日，每次一个有界周期；随后为新交易日进行质量治理、特征与面板。",
  "Sealing one receipt: the cutoffs before and after, the maintenance cycle and its effects. Published input versions are not touched.": "封存一份回执：前后截止日、维护周期及其效果。不触及已发布输入版本。",
