  "The input materializer or method identity rotated; the market data itself is unchanged. The new version re-seals the same data under the current source code.": "输入物化器或方法标识发生轮换；行情数据本身未变。新版本在当前源码下重新封存相同数据。",
  "The prepared data moved: the new version seals the current Features cutoff. Existing versions stay exactly as published.": "已准备的数据有了变化：新版本封存当前特征截止日。现有版本保持发布时的原样。",
  "An exact version already exists; nothing is re-sealed.": "精确相同的版本已存在；不会重新封存。",
