  "Confirming admits one publication Task: the prepared data is sealed as a separate immutable version. Existing versions, configured defaults and saved research stay unchanged; selecting the new version is a further explicit step.": "确认后接纳一个发布任务：已准备的数据被封存为独立的不可变版本。现有版本、配置默认值与已保存研究保持不变；选择新版本是另一个显式步骤。",
