  "{f} fit, {p} prediction and {m} metric calls by the completing execution; this page trains nothing": "完成执行进行了 {f} 次拟合、{p} 次预测与 {m} 次指标调用；本页不训练任何内容",
  "Shrinkage (fraction)": "收缩系数（比例）",
  "One-way turnover": "单边换手率",
  "Cost": "成本",
  "Net return": "净收益",
  "Cash": "现金",
  "Tracking error": "跟踪误差",
  "The Risk study's formations lie outside this book's report interval; a report-only link needs formations within the book's dates. Choose a Risk study over those dates, or a book that covers this window.": "该风险研究的形成期位于此账本的报告区间之外；仅报告层面的关联需要形成期落在账本日期之内。请选择覆盖这些日期的风险研究，或覆盖此窗口的账本。",
  "The owner found this Risk study incompatible with the book (input or formation axis); nothing was attached.": "所有者判定此风险研究与该账本不兼容（输入或形成期轴）；未附加任何内容。",
  "Listing coverage": "标的覆盖",
  "Dated scopes": "带日期的范围",
  "Left (this study)": "左侧（本研究）",
  "One selected candidate is not complete saved evidence (its Task or candidate state is shown beside it); the owner reports the pair without inventing any comparison metric. Choose a completed candidate on that side.": "所选候选之一不是完整的已保存证据（其任务或候选状态显示在旁）；所有者如实报告该配对，不虚构任何对比指标。请在该侧选择已完成的候选。",
  "Limitations": "限制",
  "The owner decides comparability; the selection is kept and nothing is re-aligned, truncated or refitted.": "可比性由所有者决定；所选保持不变，不做任何重新对齐、截断或重新拟合。",
  "Both sides name the same saved study; a comparison needs two different saved Alpha studies.": "两侧指向同一个已保存研究；对比需要两个不同的已保存 Alpha 研究。",
  "One selected Task is not saved Alpha evidence.": "所选任务之一不是已保存的 Alpha 证据。",
  "The named candidate is not among that study's recorded candidates.": "所指候选不在该研究记录的候选之中。",
  "The named candidate did not complete its evaluation; only an evaluated candidate can be compared.": "所指候选未完成评估；只有已评估的候选才能对比。",
  "One study's development receipt could not be read from its recorded artifacts.": "某研究的开发回执无法从其记录的工件中读取。",
  "One study's recorded receipt does not match its published evidence; nothing is compared against a moved artifact.": "某研究记录的回执与其已发布证据不一致；不与已移动的工件做对比。",
  "One candidate lacks a recorded result for every fold; the pair cannot be read fold by fold.": "某候选缺少部分折的记录结果；无法逐折读取该配对。",
  "One recorded receipt is not Alpha development evidence.": "某记录回执不是 Alpha 开发证据。",
  "The two studies were fitted on different exact inputs; the owner compares only candidates of the same input version.": "两项研究拟合于不同的精确输入；所有者只对比同一输入版本的候选。",
  "The two studies predict different targets; the owner compares only candidates of the same target recipe.": "两项研究预测的目标不同；所有者只对比同一目标配方的候选。",
  "The two studies' targets were materialized differently; the owner compares only candidates of the same materialization.": "两项研究的目标物化方式不同；所有者只对比同一物化方式的候选。",
  "The two studies use different feature axes; the owner compares only candidates on the same ordered features.": "两项研究使用不同的特征轴；所有者只对比相同有序特征上的候选。",
  "The two studies were scored under different metric policies; their numbers are not in the same units.": "两项研究在不同指标策略下评分；其数值单位不同。",
  "The two studies were evaluated on different causal fold policies; their folds do not pair.": "两项研究在不同的因果折策略下评估；其折无法配对。",
  "The two candidates' fold commitments differ; the owner pairs only identical fold commitments.": "两候选的折承诺不同；所有者只配对完全相同的折承诺。",
  "A candidate records the same fold commitment twice; the pair cannot be read fold by fold.": "某候选重复记录了同一折承诺；无法逐折读取该配对。",
  "The two candidates score different rows of the common surface; nothing is intersected or zero-filled to force a comparison.": "两候选在共同表面上评分的行不同；不做交集或补零来强行对比。",
