  "Answered by an agent": "由智能体回答",
  "The product runs no model of its own: an agent answers the Analyst's packet and the CRO's dossier through its bundle. Sources are prepared locally, and published work stays readable.": "产品不运行自己的模型：由智能体通过其包回答分析师的材料包和 CRO 的卷宗。来源在本地准备，已发布的工作仍可读取。",
  "Evidence work in progress": "证据工作进行中",
  "A Task is preparing or validating evidence for this book; its stages are in the work area. Nothing is inferred from it until it publishes.": "一个任务正在为此账本准备或验证证据；其阶段显示在工作区。发布之前不做任何推断。",
  "Choose the analysis to review against": "选择用于审查的分析",
