  "Names message ID {id}, declared by {n} exchanges · ambiguous, names none": "指向消息 ID {id}，但有 {n} 条交流声明了该 ID · 有歧义，不指向任何一条",
  "Recorded Main PM response · not a resolution; the objection stays as recorded": "已记录 主 PM 回应 · 不构成解决；异议按记录保留",
