  "A Main PM declaration of a research case or an assignment would name it; nothing is inferred from the messages.": "主 PM 对研究案例的声明或一项分配会命名它；不从消息中推断任何内容。",
  "exchanges": "条交流",
  "Choose a book first; its publications are listed here.": "请先选择一个账本；其发布会列在这里。",
  "The book selector is incomplete: an authored book is named by its Task, its receipt hash and its holdings date together. Open the book from its Portfolio page (Review evidence) or choose it above.": "账本选择器不完整：一个自创作的账本由其任务、回执哈希与持仓日期共同命名。请从其投资组合页面（复核证据）打开，或在上方选择。",
  "Reading the selected study…": "正在读取所选研究…",
  "Choose the other saved Alpha study first; its candidates are listed here.": "请先选择另一项已保存的 Alpha 研究；其候选会列在这里。",
  "Start command for this workspace": "此工作区的启动命令",
  "stop the idle Host and start it again without {switch}, then preview again; research execution keeps its offline policy": "停止空闲的 Host，不带 {switch} 重新启动，然后再次预览；研究执行仍保持离线策略",
  "Allow network access in Settings": "在设置中允许网络访问",
  "then preview again; the Host keeps running": "然后再次预览；Host 保持运行",
  "Its sources need the network.": "它的数据来源需要联网。",
  "Allowed by this workspace's network control.": "由此工作区的网络控制允许。",
  "Off by this workspace's network control.": "由此工作区的网络控制关闭。",
  "Off: the workspace sets no network control, so the network stays off.": "关闭：工作区未设置网络控制，因此网络保持关闭。",
  "Whether this workspace may reach its data sources.": "此工作区能否访问其数据来源。",
  "The verified source checkpoint remains recorded.": "已验证的来源检查点仍保留。",
  "No source checkpoint was captured yet.": "尚未捕获来源检查点。",
  "Nothing was admitted.": "尚未接纳任何任务。",
  "No maintained data yet": "尚无维护中的数据",
  "This workspace has no maintained data yet: a daily update maintains a prepared workspace. One explicit preparation makes it usable; nothing starts by opening this page.": "此工作区尚无维护中的数据：日常更新维护的是已准备的工作区。一次明确的准备使其可用；打开此页面不会启动任何工作。",
  "Team message": "团队消息",
  "Team hook · start": "团队钩子 · 开始",
  "Team hook · stop": "团队钩子 · 停止",
  "message kind not declared": "未声明消息种类",
  "External client declared {kind} · {state}": "外部客户端声明了 {kind} · {state}",
  "Not available yet: it follows a choice or read that has not happened.": "尚不可用：它依赖于尚未发生的选择或读取。",
