  "UNAVAILABLE": "不可用",
  "Task Control admits a cancellation request for this version.": "Task Control 接受对此版本的取消请求。",
  "Cancellation is already requested; the worker has not acknowledged it yet.": "已请求取消；工作进程尚未确认。",
  "The Task has ended ({state}); there is nothing to cancel.": "该任务已结束（{state}）；没有可取消的内容。",
  "This Task only ({short}). Verified stages, their artifacts and every published result stay exactly as recorded; nothing is deleted or recomputed.": "仅此任务（{short}）。已验证的阶段、其制品与每个已发布结果都原样保留；不删除、不重算。",
  "Cancelled at once: it never started.": "立即取消：它从未开始。",
  "This same queued Task ({short}); no new Task and no new declaration. Nothing has run; it is handed back to the worker and starts once the workspace's active place is free.": "同一个排队中的任务（{short}）；不产生新任务，也不产生新声明。尚未运行任何内容；它被交回工作进程，待工作区的活动位空出后开始。",
  "Task Control holds this Task as interrupted and this service resumes its kind.": "Task Control 将此任务记为已中断，本服务可恢复此类任务。",
  "The Task is queued and its command is still waiting its turn; nothing to resume.": "该任务在排队中，其命令仍在等待轮到自己；无需恢复。",
  "The Task is {state}; only an interrupted or parked queued Task can be resumed.": "该任务状态为{state}；只有已中断或搁置的排队中任务才能恢复。",
  "This service has no recovery command for {kind}.": "本服务没有针对 {kind} 的恢复命令。",
  "A new preview through {preview}, which records a plan and admits nothing. This Task stays exactly as recorded: nothing here is changed, cancelled or deleted.": "通过 {preview} 做一次新的预览：只记录一个计划，不接纳任何内容。此任务原样保留：这里没有任何内容被更改、取消或删除。",
  "{admitting} admits a Task and runs its actor; it is that owner's own confirmed admission, not a re-plan. This Task stays exactly as recorded.": "{admitting} 接纳一个任务并运行其行动者；这是该所有者自己的已确认接纳，不是重新规划。此任务原样保留。",
  "Nothing is admitted until {admitting} is confirmed with that owner. An identical declaration is reused exactly once this Task has succeeded (no second Task or publication); a changed one admits a new Task beside this one; while this Task runs or waits, the owner answers with its own disposition.": "在该所有者确认“{admitting}”之前，不接纳任何内容。此任务成功后，相同的声明会被精确复用（不产生第二个任务或发布）；改变后的声明会在此任务之旁接纳一个新任务；当此任务运行或等待时，所有者以其自身的处置作答。",
  "Nothing is admitted until {admitting} is confirmed with that owner, which runs an analyst or reviewer actor. An identical declaration is reused exactly once this Task has succeeded (no second Task or publication); a changed one admits a new Task beside this one; while this Task runs or waits, the owner answers with its own disposition.": "在该所有者确认“{admitting}”之前，不接纳任何内容；该所有者会运行分析或复核行动者。此任务成功后，相同的声明会被精确复用（不产生第二个任务或发布）；改变后的声明会在此任务之旁接纳一个新任务；当此任务运行或等待时，所有者以其自身的处置作答。",
  "Only {admitting}, confirmed with its owner, admits work; it runs an actor and may publish. No confirmation-free re-plan exists for this kind.": "只有经其所有者确认的 {admitting} 才接纳工作；它会运行一个行动者并可能发布。此类任务不存在免确认的重新规划。",
  "{kind} is previewed through {preview} and admitted through {admitting}, each with that owner's own confirmation.": "{kind} 通过 {preview} 预览、通过 {admitting} 接纳，各自需要该所有者的确认。",
  "No confirmation-free preview exists for {kind}; {admitting} admits.": "{kind} 不存在免确认的预览；由 {admitting} 接纳。",
