  "The sealed corpus one review reads: its issuers, documents and policy hashes, as of one instant, expiring at another.": "一次审阅所读的封存语料：其发行人、文件与政策哈希，截至某一时刻，并在另一时刻到期。",
  "A company the book holds, named by its tickers; the review concludes per issuer.": "账本持有的一家公司，以其代码命名；审阅按发行人逐一给出结论。",
  "One official document of an issuer at one revision, available from one date.": "发行人的一份官方文件，处于某一修订版本，自某日起可得。",
  "The titled part of a filing a passage sits in.": "披露文件中带标题的部分，段落所在之处。",
  "A typed disclosure the Analyst read in the filings: its issuers, direction and the spans that support or contradict it.": "分析师在披露文件中读到的一条有类型的披露：其发行人、方向，以及支持或反驳它的片段。",
  "The span handle that carries a passage to a claim; verified when the owner replays its excerpt.": "把一段原文带到一项主张的片段句柄；所有者回放其摘录后即为已验证。",
  "A material concern the CRO raised against cited findings: its severity if true, interpretation and position impact.": "CRO 针对被引发现提出的重大关切：若属实的严重度、解读与头寸影响。",
  "The CRO’s published judgement for one book and evidence version: route, completeness, issuer conclusions, required actions.": "CRO 对一个账本与证据版本发布的判断：路线、完整度、各发行人结论、必需动作。",
  "The exact prepared evidence handed to an Analyst: admitted documents and spans, bound by its context hash.": "交给分析师的精确已备证据：被采纳的文件与片段，由其上下文哈希绑定。",
  "The sealed compilation of the published analysis and the book handed to the CRO.": "把已发布分析与账本封存汇编后交给 CRO 的卷宗。",
  "A packet or a dossier as one downloadable document with its submission template.": "材料包或卷宗作为一份可下载文档，附其提交模板。",
  "The exact book a review page reads: an experiment Task, an update Task, a result or a handoff hash.": "审阅页所读的确切账本：一个实验任务、一个更新任务、一个结果或一个交接哈希。",
  "One sealed review readback pinned by its hash; preparing newer evidence never rewrites it.": "以哈希固定的一份封存审阅回读；准备更新的证据不会改写它。",
  "One saved state of a case or a filing; the head is the current one.": "案例或披露文件的一个已保存状态；头版本即当前版本。",
  "How much of the book the review reached: positions, issuers and weight, against the required minimum.": "审阅触及账本的多少：头寸、发行人与权重，对照所需最低值。",
  "Which holdings the admitted issuer registry names; an unmapped position has no issuer.": "被采纳的发行人登记册命名了哪些持仓；未映射的头寸没有发行人。",
  "How a finding is held up by its own citations: supported, single source, contested, unsupported.": "一条发现被其自身引证支撑的方式：有支持、单一来源、有争议、无支持。",
  "The route a review recommends: no material objection, accept with limits, refresh, human review, material objection.": "审阅建议的路线：无重大异议、有限接受、刷新证据、人工审阅、重大异议。",
  "Exposure": "敞口",
  "Pinned {hash} · {date}": "已钉住 {hash} · {date}",
  "Verified excerpts": "已验证摘录",
  "The research report for this exact book and evidence version, with its limits and the delivery record. A delivered report is a readback, not permission to trade.": "这个确切账本与证据版本的研究报告，含其限制与交付记录。已交付的报告是回读，不是交易许可。",
  "{m} of the positions mapped · {s} of the issuers selected": "头寸的 {m} 已映射 · 发行人的 {s} 已选择",
  "A candidate is a document the source package holds; it becomes admitted passages only after preparation, in the exact packet.": "候选是来源包持有的一份文件；只有在准备之后，它才在精确材料包中成为被采纳的段落。",
