  "At each formation, the equal-weight variance the matrix implies, and the next session's realized squared return of the same equal-weight book, as the owner recorded them; one axis, both variances.": "每个形成日：矩阵隐含的等权方差，以及同一等权账本下一交易日的实现收益平方，均为所有者记录的值；同一坐标轴，两者都是方差。",
