  "Responses only the data owner takes; they are not confirmable here.": "只由数据所有者执行的响应；此处不可确认。",
  "Resume it before anything else changes here; it removes only the targets it was approved for.": "在这里有其他变化之前先恢复它；它只删除获批的目标。",
  "Resuming is confirmed against this exact Task version; the maintenance work already recorded is kept and verified again.": "恢复会针对此确切任务版本确认；已记录的维护工作会保留并再次核验。",
  "Retrying runs the stopped stage again under the same plan; if the cause is unchanged it stops there again.": "重试会按同一计划重新运行停止的阶段；原因未变时会在该处再次停止。",
  "The Evidence library": "证据组件库",
  "The Task stopped by name.": "任务已按名称停止。",
  "The Task's own lifecycle says where it stands.": "任务自身的生命周期说明它所处的状态。",
  "The data owner asks for a new update plan before anything else; previewing one names the pending transition.": "数据所有者要求先制定新的更新计划；预览即可看到待处理的过渡。",
  "The data owner asks how to treat {names}; the update continues after you decide.": "数据所有者请你决定如何处理 {names}；你决定后更新才会继续。",
  "The data owner's own actions": "数据所有者自己的动作",
  "The exact files an approved cleanup would remove and what stays; nothing is deleted without your confirmation.": "已批准的清理将删除的确切文件以及保留的内容；未经你确认不会删除任何东西。",
  "The factors this Foundation carries into an Alpha draft, in their admitted order.": "此 Foundation 带入 Alpha 草稿的因子，按准入顺序。",
  "The handoffs start from a saved decision, never from unsaved controls. Preview derives the Foundation candidate from the decision without publishing it; sealing is a separate explicit confirmation. The Alpha draft opens on the Lab page bound to the decision and fits nothing.": "交接从已保存的决定开始，而不是未保存的控件。预览从该决定推导 Foundation 候选但不发布；封存是另一次明确确认。Alpha 草稿在研究室页面打开并绑定该决定，不做任何拟合。",
  "The last command stopped outside Task Control": "最后一条命令在 Task Control 之外停止",
  "The listings the data owner maintains; the initial cohort is backfilled, not point-in-time membership.": "数据所有者维护的标的；初始群组为回填，不是时点成员。",
  "The maintenance runner's own record for each listing the update admitted for {d}.": "维护运行器为本次更新（{d}）准入的每个标的所做的记录。",
  "The owner must assess the case again (run the update again) before a decision can be confirmed.": "所有者必须重新评估该案例（再次运行更新）后才能确认决定。",
  "The owner's recorded values": "所有者记录的值",
  "The unexplained move": "无法解释的变动",
  "The update owner names a Task, but its recovery view was not read. Tasks and the activity feed are unaffected; refresh to ask again.": "更新所有者指明了一个任务，但未读取到它的恢复视图。任务页和活动流不受影响；刷新即可再次请求。",
  "The wait is over": "等待已结束",
  "The worker may still be running a long unit, or the service that ran it may have stopped; this page does not decide. Read again once the service settles.": "工作进程可能仍在运行一个较长的单元，也可能运行它的服务已停止；本页不做判断。服务稳定后再读取。",
  "The worker runs until its next safe checkpoint, a maintenance cycle boundary; nothing already recorded is undone.": "工作进程会运行到下一个安全检查点（维护周期边界）；已记录的内容不会撤销。",
  "The working store: one explicit update at a time; publishing an input and selecting one are separate steps.": "工作存储：一次只进行一个明确的更新；发布输入与选择输入是分开的步骤。",
  "Values to four decimals, tiny non-zero values in exponent form; the exact values are in the JSON export.": "数值保留四位小数，极小的非零值用指数形式；精确值见 JSON 导出。",
  "Waiting until {time}": "等待至 {time}",
