  "The saved HTML is the original whole report. The dated JSON contains exact weights and targets; legacy generic sleeve wording does not replace this frozen policy.": "保存的 HTML 是原始完整报告。指定日期的 JSON 包含精确权重与目标仓位；旧版通用子组合文案不替代本冻结规则。",
  "Risk attribution belongs to this saved path. It is not an authored-study report link or an instruction to change weights.": "风险归因属于这条已保存路径，不是另行研究报告的关联，也不代表调整配权。",
