  "These presets have standalone registered kernels; required source dependencies are still checked by the build. The full catalog remains available in input discovery.": "这些预设具有独立注册的计算实现；构建时仍会检查必需的源数据依赖。完整目录仍可在输入发现中查看。",
  "Use Rename to change the identifier; an ordinary revision retains it.": "请使用改名操作修改标识；普通修订保留原标识。",
  "The formula statement participates in numerical identity. Use Sources / notes for description-only changes.": "公式声明参与数值身份。仅修改描述时，请使用来源／备注。",
  "Build reuses unchanged raw values and prepares only the local additions in one Task. The original input and global catalog stay unchanged; no Factor experiment or model training runs.": "一次任务复用未变的原始数值并准备本研究新增列。原输入和全局目录不变，不运行因子实验或模型训练。",
  "Prepared research features can be used directly in a Factor declaration. PLAN checks the exact input before any experiment runs.": "已准备的特征可直接用于因子研究声明。PLAN 会在实验运行前核对精确输入。",
