  "Paste the structured answer here, or drop a JSON file (up to {max} KB).": "在此粘贴结构化答复，或拖入 JSON 文件（最大 {max} KB）。",
  "Not imported": "未导入",
  "Too large to send": "过大，无法发送",
  "The owner's exact refusal": "所有者给出的原始拒绝说明",
  "This answer is {size} KB as sent; at most {max} KB is accepted.": "这份答复按发送计为 {size} KB；最多接受 {max} KB。",
  "{name} is {size} KB as sent; at most {max} KB is accepted.": "{name} 按发送计为 {size} KB；最多接受 {max} KB。",
  "{name} is {size} KB; at most {max} KB is accepted.": "{name} 为 {size} KB；最多接受 {max} KB。",
  "The Analyst answer is larger than its owner accepts; the code gives its size and the bound in bytes, counted as compact JSON. Nothing was recorded; shorten the answer and submit it again.": "分析师答复超过其所有者接受的大小；代码给出它的大小与上限（字节，按紧凑 JSON 计）。未记录任何内容；缩短答复后再提交。",
  "The CRO assessment is larger than its owner accepts; the code gives its size and the bound in bytes, counted as compact JSON. Nothing was recorded; shorten the assessment and submit it again.": "CRO 评估超过其所有者接受的大小；代码给出它的大小与上限（字节，按紧凑 JSON 计）。未记录任何内容；缩短评估后再提交。",
  "The request is larger than the service reads; the code gives the bound in bytes. Nothing was read or recorded.": "请求超过服务可读取的大小；代码给出上限（字节）。未读取也未记录任何内容。",
  "Report only (DFD′ + E); never used for weights": "仅作报告（DFD′ + E）；从不用于权重",
