  "The definition PLAN asked for earlier did not complete while you were elsewhere.": "你离开期间，先前请求的定义 PLAN 未能完成。",
  "The build Task was admitted while you were elsewhere; it is on Tasks.": "你离开期间，构建任务已被接纳；请在任务页查看。",
