  "Revoke grant": "撤销委托",
  "Grant": "委托",
  "Authorize external executor for Task {id}": "授权外部执行者处理任务 {id}",
  "Authorize this exact external decision": "授权这项精确的外部执行",
  "Revoke this external decision grant": "撤销这项外部执行委托",
  "No blocked preparation Task is available for this grant.": "当前没有可接受此委托的受阻准备任务。",
  "This grant is no longer active.": "这项委托已失效。",
  "Confirm preparation continuation": "确认继续准备",
  "This Human authorization permits an external executor to confirm only the displayed case, evidence, option and target for the named blocked preparation Task. No effect is applied by issuing it; the executor remains EXTERNAL_AUTOMATION and the owner revalidates at confirmation.": "这项人工授权仅允许外部执行者针对指定的受阻准备任务，确认所展示的案例、证据、选项与目标。签发委托不会应用处理结果；执行者仍为 EXTERNAL_AUTOMATION，确认时由负责人重新校验。",
  "Revoking stops future delegated confirmations and continuations; recorded decisions and admitted Tasks are not undone.": "撤销后不能再凭此委托确认或续跑；已记录的决定和已接纳的任务不会被撤回。",
  "This stopped Task is historical. A successor Task continued from its retained checkpoint; inspect that exact Task for the current result.": "此停止任务属于历史记录。后继任务已从保留的检查点继续；请查看该精确任务的当前结果。",
  "Inspect successor Task": "查看后继任务",
  "No new upstream work is planned for: {work}. RUN revalidates the bindings.": "本计划不重新执行这些上游工作：{work}。RUN 会重新校验绑定。",
  "Input: {input}; program: {program}; implementation: {implementation}. The original result remains historical.": "输入：{input}；程序：{program}；实现：{implementation}。原结果保留为历史记录。",
  "impact|Changed": "已变化",
  "impact|Unchanged": "未变化",
