  "Submit the CRO answer": "提交 CRO 答案",
  "The Host checks the answer against its exact binding and names any problem by item: an answer with problems is returned for correction (twice at most; the third keeps its acceptable items). An admitted answer is sealed and published as one Task with HUMAN attribution. An imported answer does not authorize its own route and does not prove an independent reviewer.": "Host 会按确切绑定检查答案，并逐项指出问题：有问题的答案会退回更正（最多两次；第三次保留可接受的条目）。被接纳的答案会作为一个任务封存并发布，署名为 HUMAN。导入的答案不能自行决定路由，也不能证明审查者是独立的。",
