  "Verify update": "验证更新",
  "Seal market observations": "封存市场观测",
  "Publish decision settlement": "发布决策结算",
  "Claim protected permit": "申领受保护许可",
  "Continue protected path": "继续受保护路径",
  "Release validated handoff": "释放已验证的交接",
  "Seal pending package": "封存待定的包",
  "Verify protected closure": "验证受保护闭包",
  "Execute and publish declared path": "执行并发布声明的路径",
  "Materialize verified lifecycle portfolio inputs": "物化已验证的生命周期投资组合输入",
  "Materialize local formula columns": "物化本地公式列",
  "Prepare local formula overlay": "准备本地公式覆盖层",
  "Publish input version": "发布输入版本",
  "Build historical tradability": "构建历史可交易性",
  "Causal execution outcome": "因果执行结果",
  "Pre research delta gate": "研究前增量闸门",
  "Build or reuse local columns and their development preprocessing; no global catalog or Factor/Alpha admission.": "构建或复用本地列及其开发预处理；不进入全局目录，也不接纳为因子或 Alpha。",
  "Build or reuse source-bound local Formula columns; no global catalog or Factor/Alpha admission.": "构建或复用绑定来源的本地公式列；不进入全局目录，也不接纳为因子或 Alpha。",
  "Continue bounded source reading of a prepared packet.": "继续对一个已准备数据包的有界来源读取。",
  "Continue the sealed book across one permitted fixture and release it once.": "让封存的账本在一个许可的固定数据上继续，并只释放一次。",
  "Execute or exactly reuse the frozen public Portfolio path and publish its report.": "执行或精确复用冻结的公开投资组合路径，并发布其报告。",
  "Interpret admitted issuer evidence against one sealed Portfolio book and return one Host-routed recommendation without action authority.": "对照一个封存的投资组合账本解读已接纳的发行人证据，并返回一条经 Host 路由、不带行动权限的建议。",
  "Prepare a component score; do not publish positions.": "准备一个组件评分；不发布持仓。",
  "Prepare causal sizing input, not positions.": "准备因果的仓位规模输入，而非持仓。",
  "Prepare current-universe research inputs, not a strategy or Foundation.": "准备当前成员集的研究输入，而非策略或 Foundation。",
  "Prepare exact evidence for every unit of the book.": "为账本的每个单元准备精确证据。",
  "Prepare exact evidence for external analysis.": "为外部分析准备精确证据。",
  "Prepare frozen-component Features, targets and supported quarters; no model fits or strategy activation.": "准备冻结组件的特征、目标与受支持的季度；不拟合模型，也不激活策略。",
  "Publish a conditional QA proposal and observed settlement.": "发布一份有条件的 QA 提议与已观测的结算。",
  "Publish governed actor-neutral official-source document intelligence.": "发布受治理、与执行者无关的官方来源文档情报。",
  "Publish governed document intelligence for every unit of the book.": "为账本的每个单元发布受治理的文档情报。",
  "Replay selected Alpha evidence through an EW research book; no activation.": "通过一个等权研究账本回放所选的 Alpha 证据；不激活。",
  "Run an admitted Alpha development experiment, not a strategy or current publication.": "运行一个已接纳的 Alpha 开发实验，而非策略或当前发布。",
  "Run an admitted Factor experiment, not a strategy or current publication.": "运行一个已接纳的因子实验，而非策略或当前发布。",
  "Run installed Risk diagnostics over a sealed research input; no allocation or activation.": "在一个封存的研究输入上运行已安装的风险诊断；不做配置，也不激活。",
  "Seal verified local inputs; no data update or strategy change.": "封存已验证的本地输入；不更新数据，也不改变策略。",
  "Update admitted inputs; retain Foundation research.": "更新已接纳的输入；保留 Foundation 研究。",
  "Update captured inputs, catch up in order, publish one complete QA branch.": "更新已捕获的输入，按顺序补齐，发布一个完整的 QA 分支。",
  "Verify every saved study's sealed evidence in full; compute nothing.": "完整验证每个已保存研究的封存证据；不做任何计算。",
  "Verify local lifecycle results and prepare frozen Portfolio inputs; no fit, book or current activation.": "验证本地生命周期结果并准备冻结的投资组合输入；不拟合、不建账本，也不做当前激活。",
  // V618 (UX06): Settings -- an installed strategy's score sources, the CPU budget's owner guidance, the queue's reasons
  "Historical array replay": "历史评分数组回放",
  "Current model scoring": "当前模型评分",
  "auto takes the processors not in use when a preparation or a Task starts. Set a number of cores only when the user asks or the machine is busy with other work. A budget changes how fast work runs, never what it computes: a book's model sessions prove the retrieval canary when they load, a Task's DuckDB and Arrow reads give the same values at any count, and an Alpha study's LightGBM fits prove their canary at the count they run on. tasks_waiting sets how many Tasks may wait behind the running one (auto: one place per four processors); a request past the last place is refused before its planning work, and a Task waiting for its recovery holds no running place.": "auto 在准备或任务开始时使用未被占用的处理器。仅在用户要求或机器正忙于其他工作时才设置核心数。预算只改变工作运行的快慢，从不改变计算结果：账本的模型会话在加载时证明检索金丝雀，任务的 DuckDB 与 Arrow 读取在任何数量下给出相同的值，Alpha 研究的 LightGBM 拟合在其运行的数量下证明其金丝雀。tasks_waiting 设置可在运行中的任务之后排队的任务数（auto：每四个处理器一个位置）；超过最后一个位置的请求在规划之前即被拒绝，等待恢复的任务不占用运行位置。",
  "auto: one waiting place per {k} of the {n} processors": "auto：{n} 个处理器中每 {k} 个对应一个排队位置",
  "set to {n}": "设为 {n}",
  // V614 (UX02): the activation's review standing, where the book's answer states none
  "Review standing not stated": "未给出复核状态",
  "Positions are held only from the trading start; its daily research update continues the forward book.": "仅从交易起点开始持有仓位；其每日研究更新会延续向前账本。",
  // CJ (UX2-01, UX2-02): the ledger's plan rule, the CRO's generated words and materiality, the packet's static gaps
  "The states name the sealed reading plan -- the inventoried units, the routed tables and the returned candidates the plan holds -- never the sources: passages no question returned, text outside the routed regions and tables without a retained original were never in the plan, and a COMPLETE plan or an exhausted budget does not say every source was read.": "这些状态说的是封存的阅读计划——计划所含的已盘点单元、已路由的表格与返回的候选——而不是来源本身：没有问题返回的段落、路由区域之外的文本以及没有保留原件的表格从未进入计划；计划为 COMPLETE 或预算用尽，都不表示每个来源都已读过。",
  "No major negative was named in the evidence read.": "在已读证据中没有指出重大负面事项。",
  "Not addressed": "未处理",
  "no admitted document held for the issuer": "该发行人没有已接纳的文档",
  "no region routes to the topic; one bounded broader pass over the issuer's documents": "没有区域路由到该主题；对该发行人的文档做一次有界的更宽泛读取",
  // CJ (UX2-01): a routed region's basis -- the structure family, the heading cue's kind, an unstructured document
