  "Each trial runs against its baseline study: an Alpha study handed off from a Factor study, or the Portfolio study built on one.": "每次试验都以其基线研究为对照：由因子研究交接而来的 Alpha 研究，或建立在其上的投资组合研究。",
  "Every trial is on the ledger; these counts are what a multiple-testing correction reads.": "每次试验都记在台账上；多重检验校正读取的正是这些计数。",
