  "The completed trial's screening evidence for this formula and, where screening admitted it, the Alpha study's change with it.": "已完成试验中此公式的筛选证据，以及在筛选接纳它时，加入它后 Alpha 研究的变化。",
  "The formula as its research plan declares it, and the recipe that preprocesses it.": "研究计划所声明的公式，以及对它进行预处理的方案。",
  "The formula factors agents declared in this workspace's research plans. An agent plans, builds and tries a formula; a person activates it into this workspace's daily catalog. Reading a packet checks its golden examples and builds nothing.": "智能体在此工作区研究计划中声明的公式因子。智能体规划、构建并试验公式；由人将其激活到此工作区的每日目录中。读取审阅包会核对其黄金示例，不构建任何内容。",
  "The formula's column in the latest trial's build.": "此公式在最近一次试验构建中的列。",
