  "In this workspace's daily catalog: its daily updates compute it.": "在此工作区的每日目录中：每日更新会计算它。",
  "Declared by an agent in a research plan; not in this workspace's daily catalog.": "由智能体在研究计划中声明；不在此工作区的每日目录中。",
  "The formula fails its contract": "该公式未通过其契约",
  "No completed trial of this formula": "此公式没有已完成的试验",
  "The daily Panel does not admit it": "每日面板不接纳它",
  "Activate this formula factor for this workspace?": "为此工作区激活这个公式因子？",
  "Deactivate this formula factor?": "停用这个公式因子？",
  "It joins this workspace's daily Feature catalog: the daily Panel is rebuilt at the next data update, every factor from the history's start. Activation records you and the time, the formula and its recipe, the trial it passed and the packet read; it edits no sealed record.": "它将加入此工作区的每日特征目录：每日面板会在下次数据更新时重建，每个因子都从历史起点重新计算。激活会记录你和时间、公式及其预处理方案、它通过的试验以及所读的审阅包；它不修改任何封存记录。",
  "It leaves this workspace's daily catalog, and the daily Panel is rebuilt at the next data update; a Panel or study that binds it still reads back.": "它将离开此工作区的每日目录，每日面板会在下次数据更新时重建；绑定它的面板或研究仍可读回。",
  "Contract fails": "契约未通过",
