  "Shipped with the product": "随产品提供",
  "A trial record no longer reads": "一条试验记录无法读取",
  "The daily Panel preprocesses with ROBUST_SECTOR_NEUTRAL_Z alone; this recipe is a research recipe. Declare the factor again with that recipe to activate it.": "每日面板只使用 ROBUST_SECTOR_NEUTRAL_Z 进行预处理；此方案是研究用方案。请用该方案重新声明因子后再激活。",
  "The research plan names no preprocessing recipe for this factor, so the daily Panel cannot admit it. Declare it again with a recipe to activate it.": "研究计划没有为此因子指定预处理方案，因此每日面板无法接纳它。请指定方案重新声明后再激活。",
  "The daily build carries no Sector level yet, so a Sector-level formula stays a research factor: it can be tried, not activated.": "每日构建尚不包含行业层级，因此行业层级的公式仍是研究因子：可以试验，不能激活。",
  "A person activates or deactivates a formula factor, in the Workbench; an agent declares, builds and tries it, and reads its review packet.": "由人在工作台中激活或停用公式因子；智能体负责声明、构建和试验它，并读取其审阅包。",
  "Retained documents not read": "保留的文档未能读取",
  "Reuse since the service started": "服务启动以来的复用",
  "What this workspace holds, from its sealed references; nothing was fetched, and no source's freshness is claimed.": "此工作区所持有的内容，依据其封存的引用；没有抓取任何内容，也不声称任何来源是最新的。",
  "at most {b} a document": "每份文档最多 {b}",
  "{a} attempts and {b} left": "剩余 {a} 次尝试和 {b}",
  "{a} documents reused, {b} fetched": "复用 {a} 份文档，抓取 {b} 份",
