  "The saved report and holdings remain pinned. Portfolio supplies the rolling outcomes and metrics; the UI does not recompute them.": "已保存的报告和持仓保持固定。投资组合提供滚动结果和指标；界面不会重新计算。",
  "Formation range {from} — {to}": "形成日范围 {from} — {to}",
  "Outcomes through {date}": "结果观测截至 {date}",
  "Outcomes through": "结果观测截至",
  "Net of {c} bps per side": "每侧净额 {c} 个基点",
  "The rolling report's sealed base, update, or link does not match its declared identity or date axis, so no performance values are shown. Restore a verified workspace backup, then read the saved study again.": "滚动报告的已封存基准、更新或链接与声明的身份或日期轴不符，因此不显示绩效数值。请恢复经过验证的工作区备份，然后重新读取已保存的研究。",
  "This book's declared cost has no sealed daily return lane. Daily updates record 5 or 10 bps per side; read a book with one of those declared costs, or report the unavailable lane. Do not substitute another cost.": "此账本声明的成本没有已封存的日收益档位。每日更新记录每侧 5 或 10 个基点；请读取声明了其中一种成本的账本，或报告该档位不可用。请勿替换为其他成本。",
  "The daily checkpoint's source book has no readable publishing Task. Read the saved studies to confirm the Task; if its retained record is missing, restore a verified workspace backup and read again.": "每日检查点的来源账本没有可读取的发布任务。请读取已保存的研究以确认该任务；如果保留记录缺失，请恢复经过验证的工作区备份后重新读取。",
  "No realized forward publication is available for this book and cost lane.": "此账本及成本档位没有可用的前瞻已实现发布记录。",
  "Realized forward source": "前瞻已实现来源",
  "This read is separate from the historical research report above.": "此读取与上方历史研究报告分开。",
  "Historical report remains pinned": "历史报告仍固定保留",
  "The research report values and holdings are still available in Historical report mode; they are not mixed into realized returns.": "历史报告模式仍可查看研究报告数值和持仓；这些内容不会混入已实现收益。",
  "Realized forward performance is an owner readback for the exact installed book and cost lane.": "前瞻已实现绩效是所有者对精确安装账本和成本档位的读取结果。",
  "The realized per-session net return as supplied by Portfolio.": "投资组合提供的逐交易日净收益。",
  "No realized observation is recorded for this window.": "此窗口未记录已实现观测。",
  "Owner-reported metric for the selected realized window; never combined with historical research metrics.": "所有者报告的所选已实现窗口指标；绝不与历史研究指标合并。",
  "Realized forward returns": "前瞻已实现收益",
  "Exact owner-supplied net simple returns for {from} — {to}; {n} observations.": "所有者提供的 {from} — {to} 精确净简单收益；{n} 个观测。",
  "The chart shows published daily returns.": "图表显示已发布的每日收益。",
  "Formation": "形成日",
