  "Last 30 observations shown; no cumulative performance is calculated here.": "显示最近 30 个观测；此处不计算累计绩效。",
  "Unreached": "未覆盖",
  "Accounted weight": "已核算权重",
  "Whole-book coverage accounting was not recorded; the floor comparison is unavailable.": "未记录全账本覆盖核算；无法与最低门槛比较。",
  "{w} of the book's weight accounted": "账本权重中已核算 {w}",
  "{w} of the book accounted · {c} of the change · as this publication sealed it": "账本已核算权重 {w} · 变更 {c} · 按本次发布封存记录",
  "Quiet window": "静默窗口",
  "The book's ending weight by what the review reached, as the owner recorded it; the mark is the route's floor.": "按所有者记录的审阅覆盖情况展示账本期末权重；标记为流程最低门槛。",
  "The saved result index could not be verified. Its Task and result contents are unknown. Read workspace show and backup list; restore a generation that holds this index into a new directory, then read the result there.": "保存的结果索引无法验证，其任务和结果内容未知。请读取 workspace show 和 backup list；把保有此索引的备份恢复到新目录，再在那里读取结果。",
  "A backup-root record could not be verified. Its sealed identity, workspace association and suitability for restore are unknown. Read workspace show and backup list; restore an appropriate verified full generation hash with alphalattice backup restore --dir <new directory> --generation <verified generation hash> --workspace-id <workspace id> --root <backup root>. Do not select an unverified filename prefix.": "备份根目录中的某条记录无法验证，其封存身份、工作区归属以及是否可用于恢复均未知。请读取 workspace show 和 backup list；用 alphalattice backup restore --dir <new directory> --generation <verified generation hash> --workspace-id <workspace id> --root <backup root> 恢复合适且已验证的完整备份哈希。不要选择未经验证的文件名前缀。",
  "This model's review packet could not be read. Repair its declaration, module, or required runtime, then run the model check command shown here.": "此模型的评审包无法读取。请修复其声明、模块或所需运行环境，再运行这里给出的模型检查命令。",
  "The named Task record could not be projected. Its lifecycle, progress and artifacts are unknown. Read workspace show and backup list; restore a generation that holds this Task into a new directory before reading it there.": "所指任务记录无法投影，其生命周期、进度及产出物未知。请读取 workspace show 和 backup list；把保有此任务的备份恢复到新目录，再在那里读取它。",
  "The named evidence artifact is missing from this workspace. Inspect storage and backup list; restore a generation that holds this artifact into a new directory before reading it there.": "此工作区缺少所指的证据产出物。请检查存储和 backup list；把保有此产出物的备份恢复到新目录，再在那里读取它。",
  "The named evidence artifact does not verify against its recorded identity. Inspect storage and backup list; restore a verified copy into a new directory before reading it there.": "所指证据产出物与其记录的身份无法核验一致。请检查存储和 backup list；把已验证的副本恢复到新目录，再在那里读取它。",
  "The named evidence artifact could not be read. Its contents are unknown. Inspect storage and backup list; restore a generation that holds it into a new directory before reading it there.": "所指证据产出物无法读取，内容未知。请检查存储和 backup list；把保有它的备份恢复到新目录，再在那里读取它。",
  "The named Task is not held by Task Control in this workspace. Read workspace show and backup list; restore a generation that holds it into a new directory, or follow the offered owner action to plan new work.": "此工作区的 Task Control 没有保存所指任务。请读取 workspace show 和 backup list；把保有它的备份恢复到新目录，或按提供的所有者操作规划新工作。",
