  "Task record missing": "任务记录缺失",
  "Part of the Task Control authority could not be read, so no state or queue order is inferred from it. Inspect workspace show and backup list. Restore a kept verified generation into a new directory with alphalattice backup restore --dir <new directory> --generation <verified generation hash> --workspace-id <workspace id> --root <backup root>, then open that workspace.": "Task Control 权威记录的一部分无法读取，因此不会据此推断状态或队列顺序。请检查 workspace show 和 backup list。用 alphalattice backup restore --dir <new directory> --generation <verified generation hash> --workspace-id <workspace id> --root <backup root> 把已保存且验证过的备份恢复到新目录，再打开那个工作区。",
