  // V656: literal producer readings, including the merged data-decision history.
  "a person, recorded for review": "由人决定，已记录供复核",
  "the owner, once confirmed": "确认后由所有者决定",
  "the owner": "所有者",
  "Your decision is recorded. It is applied when the data update continues; the owner revalidates the source evidence then.": "你的决定已记录，将在数据更新继续时应用；届时所有者会重新验证来源证据。",
  "This decision was already recorded; nothing changed.": "此决定已记录，没有改变任何内容。",
  "The Feature owner reports its status only: {status}.": "特征所有者只报告其状态：{status}。",
  "The owner waits for the source to recover, as you decided. Nothing is needed from you until then; after it, continue the update: nothing is retried on its own.": "所有者按你的决定等待来源恢复。在此之前无需你操作；恢复后请继续更新，系统不会自行重试。",
  "The owner waits for the condition it named. Nothing is needed from you until then; after it, continue the update: nothing is retried on its own.": "所有者等待其指出的条件满足。在此之前无需你操作；满足后请继续更新，系统不会自行重试。",
  "refused at execution": "执行时被拒绝",
  "ran its course": "已走完流程",
  "the owner retries then": "届时由所有者重试",
  "applied when the update continues": "在更新继续时应用",
  "The data update waits for you to continue it": "数据更新等待你继续",
  "The preparation waits for you to continue it": "准备工作等待你继续",
  "continued": "已继续",
  "Less": "收起",
  "Declaration changes": "声明变更",
  "The request was sent and refused before dispatch: its session token was not accepted and nothing was admitted. The session was renewed; confirm again to send it.": "请求已发送，但在派发前被拒绝：其会话令牌未被接受，没有准入任何操作。会话已更新；请再次确认以发送请求。",
  "The request was sent and refused before dispatch: its session token was not accepted and nothing was admitted. Renewing the session failed; reload the page for a new session, then confirm again.": "请求已发送，但在派发前被拒绝：其会话令牌未被接受，没有准入任何操作。会话更新失败；请重新加载页面以获取新会话，然后再次确认。",

  // U117: explicit owner words and an honest absent-word state.
  "Word not declared": "尚未声明用词",
  "Task heartbeat not recent": "任务心跳未及时更新",
  "Task runner heartbeat not observed": "未观测到任务执行器心跳",
  "Task work may be stalled": "任务工作可能已停滞",
  "Task awaiting recovery": "等待恢复的任务",
  "Queued Task without a driving command": "无命令驱动的排队任务",
  "The Task is running but its heartbeat has not been seen recently; it may have stopped without the Host knowing. Its verified stages are kept.": "任务处于运行状态，但近期未观测到心跳；它可能已停止，而 Host 尚未获知。已验证的阶段仍然保留。",
  "The Task is running but the Host cannot read its runner's heartbeat, so whether it is alive is not observed. Its verified stages are kept.": "任务处于运行状态，但 Host 无法读取其执行器的心跳，因此尚未观测到它是否仍在运行。已验证的阶段仍然保留。",
  "The Task's current stage has run longer than the Host's policy allows while its heartbeat stays fresh: its work may be stuck. Its verified stages are kept.": "任务当前阶段的运行时间已超过 Host 策略允许的时长，但心跳仍及时更新：工作可能已停滞。已验证的阶段仍然保留。",
  "The Task stopped before it ended and waits for a recovery; its verified stages are kept and only unverified work would run again.": "任务在结束前停止，正在等待恢复；已验证的阶段仍然保留，只会重新执行尚未验证的工作。",
  "The Task is queued but no command of this Host drives it any more; a recovery hands it back to the worker.": "任务仍在排队，但此 Host 已无命令驱动它；恢复操作会将它交回工作进程。",
