  "The Host reads the usage of the agent Sessions bound to this workspace from their own session files when a goal is taken or submitted, an answer is submitted or a Team or Goal page opens. It keeps models, efforts, token counts and times, never conversation text.": "在领取或提交目标、提交答案、或打开团队或目标页面时，Host 从绑定到此工作区的智能体会话自己的会话文件中读取用量。它保留模型、推理强度、令牌数和时间，从不保留对话文本。",
