  "Owner return unit": "所有者收益单位",
  "Annualization sessions": "年化交易日数",
  "Volatility degrees of freedom": "波动率自由度",
  "Sharpe cash return per session": "Sharpe 每交易日现金收益",
  "Sortino downside threshold": "Sortino 下行阈值",
  "No eligible realized forward publication was returned for this book and cost lane.": "此账本与成本档位未返回符合条件的前瞻已实现发布记录。",
  "Requested exact book task": "请求的准确账本任务",
  "Strategy package": "策略包",
